def test_tc101_a_new_pet_can_be_read_back_by_its_id(api, context):
    """A new pet can be read back by its id. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /pet
    response = api.post("/pet", json={
        "id": 7310001001,
        "name": f"qa-agent-{unique}",
        "photoUrls": [],
        "status": "available",
    })
    Expect(response).status_is(200).field_equals("status", "available")
